using System.Text;
using System.Security.Cryptography;
using PhotoTrail.Windows;
static class PresetLibraryChecks
{
 public static void Run(){int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);passed++;}void Reject(Action action,string name){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,name);}
 string root=Path.Combine(Path.GetTempPath(),"PhotoTrail-preset-library-"+Guid.NewGuid());Directory.CreateDirectory(root);string file=Path.Combine(root,"library.json");
 var empty=MetadataPresetLibrary.Open(file);Check(empty.Entries.Count==0&&!File.Exists(file),"missing-library-empty-no-seed-or-write");
 var ops=new[]{new MetadataOperation("XMP-dc:Title","setText","first"),new MetadataOperation("XMP-dc:Title","appendText","+"),new MetadataOperation("XMP-dc:Description","copy","XMP-dc:Title")};var original=new MetadataPresetEntry(Guid.NewGuid(),MetadataPreset.Create("示例",ops));var saved=MetadataPresetLibrary.Save(file,empty,[original]);Check(saved.Revision==MetadataPresetLibrary.Open(file).Revision,"atomic-encoding-revision-agrees");Check(saved.Entries.Single().Preset.Operations.SequenceEqual(ops),"repeated-target-order-and-parameters-roundtrip");
 var stale=MetadataPresetLibrary.Open(file);var update=original with{Preset=MetadataPreset.Create("示例",[new("XMP-dc:Title","setText","updated")])};saved=MetadataPresetLibrary.Save(file,saved,[update]);Check(saved.Entries.Single().Id==original.Id,"update-preserves-identity");Reject(()=>MetadataPresetLibrary.Save(file,stale,[original]),"stale-snapshot-refuses-overwrite");Check(MetadataPresetLibrary.Open(file).Entries.Single().Preset.Operations.Single().Value=="updated","conflict-keeps-new-disk");
 var clone=new MetadataPresetEntry(Guid.NewGuid(),MetadataPreset.Create(MetadataPresetLibrary.UniqueName("示例",saved.Entries,true),original.Preset.Operations));saved=MetadataPresetLibrary.Save(file,saved,[update,clone]);Check(clone.Preset.Name=="示例 2"&&clone.Id!=update.Id&&clone.Preset.Operations.SequenceEqual(ops),"saved-copy-independent-id-content");Check(MetadataPresetLibrary.UniqueName("示例",saved.Entries,true)=="示例 3","smallest-available-numeric-suffix");Check(MetadataPresetLibrary.UniqueName("示例",[clone])=="示例","import-original-name-when-available");
 var renamed=update with{Preset=MetadataPreset.Create("  新名称  ",update.Preset.Operations)};saved=MetadataPresetLibrary.Save(file,saved,[renamed,clone]);Check(saved.Entries[0].Id==update.Id&&saved.Entries[0].Preset.Name=="新名称"&&saved.Entries[0].Preset.Operations.SequenceEqual(update.Preset.Operations),"rename-trims-keeps-position-and-operations");Reject(()=>MetadataPresetLibrary.Save(file,saved,[renamed,clone with{Preset=MetadataPreset.Create("新名称",ops)}]),"exact-name-collision-rejected");Check(MetadataPresetLibrary.Decode(MetadataPresetLibrary.Encode([original,original with{Id=Guid.NewGuid(),Preset=MetadataPreset.Create("示例".ToUpperInvariant()+"A",ops)}])).Length==2,"distinct-exact-names-accepted");var caseEntries=new[]{original with{Preset=MetadataPreset.Create("A",ops)},clone with{Preset=MetadataPreset.Create("a",ops)}};Check(MetadataPresetLibrary.Decode(MetadataPresetLibrary.Encode(caseEntries)).Length==2,"case-sensitive-Mac-name-comparison");
 Check(MetadataPresetLibrary.UniqueName(new string('x',77)+"😀",[],true)==new string('x',77)+" 2","numeric-name-does-not-split-UTF16-pair");var json=MetadataPresetLibrary.Encode([original]);foreach(var bad in new[]{json.Replace("\"version\":1","\"version\":2"),json.Replace("\"version\":1","\"version\":1,\"version\":1"),json.Replace("\"format\":","\"unknown\":0,\"format\":"),json.Replace(original.Id.ToString(),Guid.Empty.ToString()),json.Replace(original.Id.ToString(),"bad"),json.Replace("setText","unknown"),json.Replace("XMP-dc:Title","unknown"),json.Replace("\"name\":","\"name\":\"duplicate\",\"name\":"),"{",json+new string(' ',MetadataPresetLibrary.MaximumBytes)})Reject(()=>MetadataPresetLibrary.Decode(bad),"invalid-library-rejected-"+passed);
 Reject(()=>MetadataPresetLibrary.Encode([original,original]),"duplicate-id-rejected");Reject(()=>MetadataPresetLibrary.Encode([original,original with{Id=Guid.NewGuid()}]),"duplicate-name-rejected");Reject(()=>MetadataPresetLibrary.Encode([original with{Preset=new("empty",Array.Empty<MetadataOperation>())}]),"empty-chain-rejected");
 var entries=Enumerable.Range(0,256).Select(i=>new MetadataPresetEntry(Guid.NewGuid(),MetadataPreset.Create("item "+i,ops))).ToArray();Check(MetadataPresetLibrary.Decode(MetadataPresetLibrary.Encode(entries)).Length==256,"256-entry-boundary");Reject(()=>MetadataPresetLibrary.Encode(entries.Append(new(Guid.NewGuid(),MetadataPreset.Create("overflow",ops))).ToArray()),"257-entries-rejected");Reject(()=>MetadataPresetLibrary.Encode(entries.Select(x=>x with{Preset=MetadataPreset.Create(x.Preset.Name,[new("XMP-dc:Description","setText",new string('a',8192))])}).ToArray()),"aggregate-one-MiB-boundary");Reject(()=>MetadataPresetLibrary.Name("bad\nname"),"name-control-rejected");Reject(()=>MetadataPresetLibrary.Name(new string('x',81)),"81-name-rejected");
 var bytes=File.ReadAllBytes(file);using(var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){Reject(()=>MetadataPresetLibrary.Save(file,saved,[]),"write-replacement-failure");Check(File.ReadAllBytes(file).SequenceEqual(bytes),"write-failure-original-unchanged");}Check(MetadataPresetLibrary.Open(file).Revision==saved.Revision,"write-failure-not-marked-new-revision");
 File.WriteAllBytes(file,[0xff,0xfe,0x7b,0]);Reject(()=>MetadataPresetLibrary.Open(file),"strict-UTF8-rejects-UTF16");var broken=File.ReadAllBytes(file);Reject(()=>MetadataPresetLibrary.Save(file,saved,[]),"corrupt-disk-cannot-overwrite");Check(File.ReadAllBytes(file).SequenceEqual(broken),"corrupt-original-kept");File.WriteAllText(file,"{\"version\":2}");Reject(()=>MetadataPresetLibrary.Open(file),"damaged-schema-not-empty-reset");File.WriteAllBytes(file,bytes);saved=MetadataPresetLibrary.Open(file);saved=MetadataPresetLibrary.Save(file,saved,[]);Check(File.Exists(file)&&MetadataPresetLibrary.Open(file).Entries.Count==0,"deleted-all-persists-empty-no-seed");
 var single=MetadataPreset.Decode(original.Preset.Encode());Check(single.Name==original.Preset.Name&&single.Operations.SequenceEqual(ops)&&!original.Preset.Encode().Contains(original.Id.ToString()),"single-JSON-no-library-id");Console.WriteLine("PRESET_LIBRARY_MODEL="+passed);
 }
}
